import json
import random
import statistics
from pathlib import Path

p = Path(__file__).parent
load = lambda f: json.loads(Path(f).read_text())
groups = {name: [] for name in ['same-before', 'same-after', 'paired']}
for name in load(p / 'release-summary.json'):
    run = load(p / name / 'runs.json')
    block = []
    for pair in range(run['pair_count']):
        rows = {r['label']: r for r in run['runs'] if r['pair'] == pair}
        counters = {label: {r['event']: float(r['counter-value']) for r in row['counters']}
                    for label, row in rows.items()}
        deltas = {metric: 100 * (stat(rows['after']['samples_ms']) / stat(rows['before']['samples_ms']) - 1)
                  for metric, stat in [('median_time_pct', statistics.median), ('mean_time_pct', statistics.mean)]}
        for event in ['instructions:u', 'cycles:u', 'branches:u', 'branch-misses:u', 'task-clock:u']:
            deltas[event] = 100 * (counters['after'][event] / counters['before'][event] - 1)
        block.append({'directory': name, 'pair': pair, 'deltas': deltas})
    groups[run['scenario']].append(block)

analysis = {}
for scenario, blocks in groups.items():
    assert len(blocks) == 6
    assert all(len(block) == (8 if scenario == 'paired' else 4) for block in blocks)
    flattened = [row for block in blocks for row in block]
    metrics = {}
    for metric in flattened[0]['deltas']:
        rng = random.Random(88)
        values = [[row['deltas'][metric] for row in block] for block in blocks]
        samples = sorted(statistics.median([v for block in values for v in rng.choices(block, k=len(block))])
                         for _ in range(10000))
        metrics[metric] = {'median_paired_change_pct': statistics.median(row['deltas'][metric] for row in flattened),
                           'stratified_bootstrap_95_interval': [samples[249], samples[9749]],
                           'round_median_changes_pct': [statistics.median(block) for block in values]}
    lower, upper = metrics['median_time_pct']['stratified_bootstrap_95_interval']
    analysis[scenario] = {'pairs': len(flattened), 'metrics': metrics, 'source_pairs': flattened,
                          'same_mode_precision_target_met': -1 <= lower and upper <= 1 if scenario != 'paired' else None}
    print(scenario, json.dumps({k: v for k, v in metrics.items() if k in ['median_time_pct', 'mean_time_pct', 'instructions:u']}, indent=2), flush=True)
(p / 'analysis.json').write_text(json.dumps(analysis, indent=2) + '\n')
